    knownrebecs {
        Pong pong;
    }
    statevars {
        int count;
    }

    Ping() {
        count = 0;
    }

    msgsrv initial() {
        // corresponds to StartMessage
        pingStart();
    }

    msgsrv pingStart() {
        // println("Ping started the game!");
        pong.pingMessage();
    }

    msgsrv pongMessage() {
        count = count + 1;
        // println("Ping received pong #count from pong");
        if (count >= 10) {
            pong.stopMessage();
            // println("Ping stopped");
            // no explicit stop; model ends interaction
        } else {
            pong.pingMessage();
        }
    }
}

